use super::*;
use crate::pet_runtime::{admission_tests::{Fixture,evidence},authority_tests::{root,queued},authority_store::mutate_with_authority,store::Fault,model::{Action,State}};
use std::{fs::{self,OpenOptions},os::fd::AsRawFd};
fn setup(provider:&str)->(Fixture,Authority,Record,Chat,Pending){
    let f=Fixture::new();let a=Authority::ensure(&root(&f)).unwrap();let g=queued(&f,&f.goal(provider),&a);let main=Chat::persistent(f.path.join("live.json"));let controller=Controller::new().unwrap();
    let pending=controller.prepare(&g,&root(&f),&f.path.join("contexts"),&main,&evidence(&g,100_006),"original-native-claim".into(),100_006,Arc::new(|_,_,_|Validity::Current)).unwrap();(f,a,g,main,pending)
}
fn body(f:&Fixture,g:&Record)->serde_json::Value{serde_json::from_slice::<serde_json::Value>(&fs::read(root(f).join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap()).unwrap()["body"].clone()}
#[test]fn unactivated_claim_with_real_catalog_contention_can_be_paused_or_cancelled_for_every_pet(){
    for provider in ["codex","copilot","antigravity","ollama"]{for action in [Action::Pause,Action::Cancel]{
        let(f,a,g,main,pending)=setup(provider);let lock=OpenOptions::new().read(true).write(true).open(f.path.join("goals/.catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_SH|libc::LOCK_NB)},0);
        assert!(matches!(pending.claim(&f.store(),&a,&evidence(&g,100_007),100_007),Err(model::Error::Busy)));assert!(pending.hold().occupies_slot());assert_eq!(pending.workers(),0);assert!(f.store().read(&g.id,&g.spec.owner.pet_id).unwrap().admissions[0].lease.is_none());drop(lock);
        let cancelled=matches!(action,Action::Cancel);let expected=if cancelled{State::Cancelled}else{State::Paused};let stopped=mutate_with_authority(&f.store(),&root(&f),&g.id,&g.spec.owner.pet_id,&g.revision,"stop-before-activation".into(),action,100_008).unwrap().record;assert_eq!(stopped.state,expected);
        let proof=pending.abort().unwrap();let receipt=f.store().drain_owned(&a,&proof,100_009).unwrap();assert_eq!(receipt.record.state,expected);assert_eq!(receipt.record.admissions[0].lease.as_ref(),Some(pending.lease()));assert_eq!(receipt.record.events.iter().filter(|e|matches!(e.kind,model::EventKind::ClaimAbandoned)).count(),1);assert!(!receipt.record.events.iter().any(|e|matches!(e.kind,model::EventKind::LeaseClaimed)));
        let terminal=body(&f,&g);assert_eq!(terminal["phase"],"revoked");assert!(terminal.get("runtimeOwner").is_none());assert_eq!(terminal.get("budgetUsage"),None);pending.hold().release_drained(&proof).unwrap();let next=main.runtime_resources().acquire(provider,Arc::default(),None).unwrap();assert!(next.current());
        let again=f.store().drain_owned(&a,&proof,100_010).unwrap();assert_eq!(serde_json::to_value(&again.record).unwrap(),serde_json::to_value(&receipt.record).unwrap());assert_eq!(body(&f,&g),terminal);pending.hold().release_drained(&proof).unwrap();assert!(next.current());
    }}
}
#[test]fn expired_unactivated_claim_closes_without_activation_or_renewing_the_original_budget(){
    let(f,a,g,_main,pending)=setup("ollama");let proof=pending.abort().unwrap();let receipt=f.store().drain_owned(&a,&proof,200_001).unwrap();assert_eq!(receipt.record.state,State::RecoveryRequired);assert_eq!(receipt.record.admissions[0].stop_reason,Some(super::super::leases::StopReason::Expired));assert_eq!(receipt.record.admissions[0].spec.budget,g.admissions[0].spec.budget);assert_eq!(pending.workers(),0);assert_eq!(body(&f,&g)["phase"],"closed");assert!(body(&f,&g).get("runtimeOwner").is_none());
}
#[test]fn cancellation_between_grant_close_and_goal_commit_is_monotonic_and_keeps_the_original_proof(){
    let(f,a,g,main,pending)=setup("ollama");let(leased,owner)=pending.claim(&f.store(),&a,&evidence(&g,100_007),100_007).unwrap();let owner=owner.unwrap();let stopped=mutate_with_authority(&f.store(),&root(&f),&g.id,&g.spec.owner.pet_id,&leased.record.revision,"pause-before-close".into(),Action::Pause,100_008).unwrap().record;
    let proof=owner.drain(DrainOutcome::Confirmed).unwrap();let mut store=f.store();store.fault=Fault::BeforePublish;assert!(store.drain_owned(&a,&proof,100_009).is_err());let closed=body(&f,&g);assert_eq!(closed["phase"],"closed");assert_eq!(closed["stopReason"],"pause");assert!(main.runtime_resources().acquire("ollama",Arc::default(),None).is_err());
    let cancelled=mutate_with_authority(&f.store(),&root(&f),&g.id,&g.spec.owner.pet_id,&stopped.revision,"cancel-partial-close".into(),Action::Cancel,100_010).unwrap().record;assert_eq!(cancelled.state,State::Stopping);let terminal=f.store().drain_owned(&a,&proof,100_011).unwrap();assert_eq!(terminal.record.state,State::Cancelled);let revoked=body(&f,&g);assert_eq!(revoked["phase"],"revoked");assert_eq!(revoked["stopReason"],"cancel");assert_eq!(revoked["closedAt"],closed["closedAt"]);assert_eq!(revoked["runtimeOwner"],closed["runtimeOwner"]);owner.live.hold.release_drained(&proof).unwrap();assert!(main.runtime_resources().busy().unwrap().is_empty());
}
#[test]fn signed_claim_without_goal_publication_can_be_stopped_before_any_worker_is_activated(){
    for action in [Action::Pause,Action::Cancel]{
        let(f,a,g,main,pending)=setup("ollama");let mut store=f.store();store.fault=Fault::BeforePublish;assert!(pending.claim(&store,&a,&evidence(&g,100_007),100_007).is_err());assert_eq!(body(&f,&g)["phase"],"claimed");assert!(f.store().read(&g.id,"ai_ollama").unwrap().admissions[0].lease.is_none());
        let expected=if matches!(action,Action::Cancel){State::Cancelled}else{State::Paused};let stopped=mutate_with_authority(&f.store(),&root(&f),&g.id,"ai_ollama",&g.revision,"stop-unpublished-claim".into(),action,100_008).unwrap();assert_eq!(stopped.record.state,expected);assert_eq!(pending.workers(),0);let proof=pending.abort().unwrap();let ended=f.store().drain_owned(&a,&proof,100_009).unwrap();assert_eq!(ended.record.state,expected);pending.hold().release_drained(&proof).unwrap();assert!(main.runtime_resources().busy().unwrap().is_empty());assert!(!ended.record.events.iter().any(|e|matches!(e.kind,model::EventKind::LeaseClaimed)));
    }
}
#[test]fn cancellation_after_uncertain_goal_close_can_ack_the_original_proof_without_reopening(){
    let(f,a,g,main,pending)=setup("ollama");let(leased,owner)=pending.claim(&f.store(),&a,&evidence(&g,100_007),100_007).unwrap();let owner=owner.unwrap();let stopped=mutate_with_authority(&f.store(),&root(&f),&g.id,"ai_ollama",&leased.record.revision,"pause-before-uncertain-goal-ack".into(),Action::Pause,100_008).unwrap().record;
    let proof=owner.drain(DrainOutcome::Confirmed).unwrap();let mut store=f.store();store.fault=Fault::AfterPublish;let uncertain=store.drain_owned(&a,&proof,100_009).unwrap();assert_eq!(uncertain.status,model::CommitStatus::Uncertain);assert_eq!(uncertain.record.state,State::Paused);let old=body(&f,&g);
    let cancelled=mutate_with_authority(&f.store(),&root(&f),&g.id,"ai_ollama",&uncertain.record.revision,"cancel-after-uncertain-goal-ack".into(),Action::Cancel,100_010).unwrap();assert_eq!(cancelled.record.state,State::Cancelled);let ack=f.store().drain_owned(&a,&proof,100_011).unwrap();assert_eq!(ack.record.state,State::Cancelled);assert_eq!(body(&f,&g)["closedAt"],old["closedAt"]);assert_eq!(body(&f,&g)["phase"],"revoked");owner.live.hold.release_drained(&proof).unwrap();assert!(main.runtime_resources().busy().unwrap().is_empty());assert!(stopped.admissions[0].stop_reason.is_some());
}
#[test]fn cancel_revocation_waits_for_its_exact_projection_before_acknowledging_a_partial_close(){
    let(f,a,g,_main,pending)=setup("ollama");let(leased,owner)=pending.claim(&f.store(),&a,&evidence(&g,100_007),100_007).unwrap();let owner=owner.unwrap();let stopped=mutate_with_authority(&f.store(),&root(&f),&g.id,"ai_ollama",&leased.record.revision,"pause-partial-before-cancel-projection".into(),Action::Pause,100_008).unwrap().record;let proof=owner.drain(DrainOutcome::Confirmed).unwrap();let mut store=f.store();store.fault=Fault::BeforePublish;assert!(store.drain_owned(&a,&proof,100_009).is_err());
    let row=&stopped.admissions[0];a.request_stop(&row.spec,row.proof.as_ref().unwrap(),super::super::leases::StopReason::Cancel,100_010).unwrap();assert_eq!(f.store().drain_owned(&a,&proof,100_011).err(),Some(model::Error::Busy));assert_eq!(f.store().read(&g.id,"ai_ollama").unwrap().revision,stopped.revision);
    f.store().mutate(&g.id,"ai_ollama",&stopped.revision,"project-original-cancel".into(),Action::Cancel,100_012).unwrap();assert_eq!(f.store().drain_owned(&a,&proof,100_013).unwrap().record.state,State::Cancelled);
}
